G=load()
def solve(inp, even_col, odd_col):
    H,W=len(inp),len(inp[0])
    cnt=collections.Counter(x for r in inp for x in r)
    seedpos={(i,j) for i in range(H) for j in range(W) if cnt[inp[i][j]]<=4}
    # OPEN = least frequent non-seed color
    others=[c for c in cnt if c not in {inp[i][j] for i,j in seedpos}]
    oc=min(others,key=lambda c:cnt[c])
    dist={p:0 for p in seedpos}; dq=collections.deque(seedpos)
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and (ni,nj) not in dist and inp[ni][nj]==oc:
                dist[(ni,nj)]=dist[(i,j)]+1; dq.append((ni,nj))
    out=[r[:] for r in inp]
    for (i,j),dd in dist.items():
        if (i,j) not in seedpos:
            out[i][j]= even_col if dd%2==0 else odd_col
    return out
